    exp = inputs['exp']
    mod = inputs['mod']

    # Matrix multiplication modulo mod
    def matrix_mult(A, B, mod):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    # Matrix exponentiation using binary exponentiation
    def matrix_pow(M, exp, mod):
        n = len(M)
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result = matrix_pow(M, exp, mod)

    # Sum all entries
    total = sum(sum(row) for row in result) % mod
    return float(total)

